"use client";

import { useCallback, useEffect, useState } from "react";
import {
  getFinanceReport,
  exportFinanceCsv,
  exportFinanceXlsx,
  exportFinancePdf,
} from "@/services/financeAdminService";
import { formatCOP } from "@/lib/formatCurrency";
import { PAYMENT_METHOD_LABELS } from "@/lib/orderLabels";

const PERIOD_OPTIONS = [
  { value: "week", label: "7 días" },
  { value: "month", label: "Mes actual" },
  { value: "quarter", label: "Trimestre" },
  { value: "year", label: "Año" },
  { value: "all", label: "Histórico" },
];

function TrendBars({ trend }) {
  if (!trend?.length) return null;
  const max = Math.max(...trend.map((t) => t.grossProfit || 0), 1);

  return (
    <div className="finance-trend">
      {trend.map((row) => (
        <div key={row.month} className="finance-trend__item">
          <div className="finance-trend__bar-wrap">
            <div
              className="finance-trend__bar finance-trend__bar--revenue"
              style={{
                height: `${Math.max(8, (row.productRevenue / max) * 100)}%`,
              }}
              title={`Ingresos: ${formatCOP(row.productRevenue)}`}
            />
            <div
              className="finance-trend__bar finance-trend__bar--profit"
              style={{
                height: `${Math.max(8, (row.grossProfit / max) * 100)}%`,
              }}
              title={`Ganancia: ${formatCOP(row.grossProfit)}`}
            />
          </div>
          <span className="finance-trend__label">{row.month}</span>
          <span className="finance-trend__meta">{row.orders} ped.</span>
        </div>
      ))}
      <div className="finance-trend__legend">
        <span>
          <i className="finance-trend__dot finance-trend__dot--revenue" /> Ingresos
        </span>
        <span>
          <i className="finance-trend__dot finance-trend__dot--profit" /> Ganancia bruta
        </span>
      </div>
    </div>
  );
}

export default function FinanceDashboard() {
  const [range, setRange] = useState("month");
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [exporting, setExporting] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const res = await getFinanceReport({ range });
      setData(res);
    } catch (err) {
      setData(null);
      const apiMsg = err.response?.data?.message;
      setError(
        err.response?.status === 403
          ? "Solo el superadministrador puede ver finanzas."
          : apiMsg || "No se pudo cargar el panel financiero."
      );
    } finally {
      setLoading(false);
    }
  }, [range]);

  const handleExport = async (type) => {
    setExporting(type);
    try {
      const params = { range };
      if (type === "csv") await exportFinanceCsv(params);
      else if (type === "xlsx") await exportFinanceXlsx(params);
      else await exportFinancePdf(params);
    } catch {
      setError("No se pudo exportar el reporte. Intenta de nuevo.");
    } finally {
      setExporting(null);
    }
  };

  useEffect(() => {
    load();
  }, [load]);

  if (loading) {
    return <p className="auth-loading">Cargando finanzas...</p>;
  }

  if (error && !data) {
    return (
      <div className="finance-dashboard">
        <p style={{ color: "#b33" }}>{error}</p>
        <button type="button" className="admin-btn" onClick={load}>
          Reintentar
        </button>
      </div>
    );
  }

  if (!data) {
    return <p style={{ color: "#b33" }}>Sin datos</p>;
  }

  const { sales, inventory, pending, paymentMethods, monthlyTrend, notes, period: periodInfo } =
    data;

  return (
    <div className="finance-dashboard">
      <div className="admin-page__header-row">
        <div>
          <p className="finance-period-label">{periodInfo?.label}</p>
        </div>
        <div className="finance-toolbar">
          <div className="finance-period-tabs">
            {PERIOD_OPTIONS.map((opt) => (
              <button
                key={opt.value}
                type="button"
                className={`finance-period-tabs__btn${range === opt.value ? " finance-period-tabs__btn--active" : ""}`}
                onClick={() => setRange(opt.value)}
              >
                {opt.label}
              </button>
            ))}
          </div>
          <div className="finance-export-btns">
            <button
              type="button"
              className="admin-btn admin-btn--sm"
              disabled={!!exporting}
              onClick={() => handleExport("csv")}
            >
              {exporting === "csv" ? "Exportando…" : "CSV"}
            </button>
            <button
              type="button"
              className="admin-btn admin-btn--sm"
              disabled={!!exporting}
              onClick={() => handleExport("xlsx")}
            >
              {exporting === "xlsx" ? "Exportando…" : "Excel"}
            </button>
            <button
              type="button"
              className="admin-btn admin-btn--sm"
              disabled={!!exporting}
              onClick={() => handleExport("pdf")}
            >
              {exporting === "pdf" ? "Exportando…" : "PDF"}
            </button>
          </div>
        </div>
      </div>

      {sales.ordersCount === 0 && (
        <div className="finance-empty" role="status">
          No hay ventas pagadas en este período. Los totales aparecen en cero; el
          inventario y la tendencia de meses anteriores siguen visibles.
        </div>
      )}

      {notes?.length > 0 && (
        <div className="finance-notes">
          {notes.map((note) => (
            <p key={note}>{note}</p>
          ))}
        </div>
      )}

      <section className="admin-dashboard-section">
        <h2 className="admin-dashboard-section__title">Ventas y ganancias</h2>
        <div className="admin-stats">
          <div className="admin-stat-card admin-stat-card--highlight">
            <p className="admin-stat-card__value">{formatCOP(sales.grossProfit)}</p>
            <p className="admin-stat-card__label">Ganancia bruta estimada</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{sales.grossMarginPct}%</p>
            <p className="admin-stat-card__label">Margen bruto</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">
              {formatCOP(sales.productRevenue)}
            </p>
            <p className="admin-stat-card__label">Ingresos por productos</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{formatCOP(sales.cogs)}</p>
            <p className="admin-stat-card__label">Costo de ventas (COGS)</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">
              {formatCOP(sales.totalCollected)}
            </p>
            <p className="admin-stat-card__label">Total cobrado (pedidos)</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{sales.ordersCount}</p>
            <p className="admin-stat-card__label">Pedidos pagados</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{sales.unitsSold}</p>
            <p className="admin-stat-card__label">Unidades vendidas</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">
              {formatCOP(sales.averageOrderValue)}
            </p>
            <p className="admin-stat-card__label">Ticket promedio</p>
          </div>
        </div>
        <div className="finance-substats">
          <span>Envío cobrado: {formatCOP(sales.shippingCollected)}</span>
          <span>Impuestos: {formatCOP(sales.taxCollected)}</span>
          <span>Descuentos: {formatCOP(sales.discountsGiven)}</span>
          <span className={pending.amount > 0 ? "finance-warn" : ""}>
            Por cobrar: {formatCOP(pending.amount)} ({pending.ordersCount} ped.)
          </span>
          {sales.itemsMissingCost > 0 && (
            <span className="finance-warn">
              {sales.itemsMissingCost} uds vendidas sin costo registrado
            </span>
          )}
        </div>
      </section>

      <section className="admin-dashboard-section">
        <h2 className="admin-dashboard-section__title">Tendencia (6 meses)</h2>
        <TrendBars trend={monthlyTrend} />
      </section>

      <section className="admin-dashboard-section">
        <h2 className="admin-dashboard-section__title">Inventario e inversión</h2>
        <div className="admin-stats admin-stats--compact">
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">
              {formatCOP(inventory.investmentAtCost)}
            </p>
            <p className="admin-stat-card__label">Valor invertido (costo)</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">
              {formatCOP(inventory.potentialRetail)}
            </p>
            <p className="admin-stat-card__label">Valor venta potencial</p>
          </div>
          <div className="admin-stat-card admin-stat-card--highlight">
            <p className="admin-stat-card__value">
              {formatCOP(inventory.potentialProfit)}
            </p>
            <p className="admin-stat-card__label">Ganancia potencial stock</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{inventory.potentialMarginPct}%</p>
            <p className="admin-stat-card__label">Margen potencial</p>
          </div>
          <div className="admin-stat-card">
            <p className="admin-stat-card__value">{inventory.unitsInStock}</p>
            <p className="admin-stat-card__label">Unidades en stock</p>
          </div>
          {inventory.productsMissingCost > 0 && (
            <div className="admin-stat-card">
              <p className="admin-stat-card__value finance-warn">
                {inventory.productsMissingCost}
              </p>
              <p className="admin-stat-card__label">Productos sin costo</p>
            </div>
          )}
        </div>
      </section>

      <div className="finance-grid-2">
        <section className="admin-dashboard-section">
          <h2 className="admin-dashboard-section__title">Top por ingresos</h2>
          <div className="admin-table-wrap">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Producto</th>
                  <th>Uds</th>
                  <th>Ingresos</th>
                  <th>Ganancia est.</th>
                </tr>
              </thead>
              <tbody>
                {sales.topByRevenue?.length ? (
                  sales.topByRevenue.map((row) => (
                    <tr key={row.productId}>
                      <td>{row.name}</td>
                      <td>{row.units}</td>
                      <td>{formatCOP(row.revenue)}</td>
                      <td>{formatCOP(row.profit)}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={4}>Sin ventas en el período</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        <section className="admin-dashboard-section">
          <h2 className="admin-dashboard-section__title">Top por ganancia</h2>
          <div className="admin-table-wrap">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Producto</th>
                  <th>Margen</th>
                  <th>Ganancia</th>
                </tr>
              </thead>
              <tbody>
                {sales.topByProfit?.length ? (
                  sales.topByProfit.map((row) => (
                    <tr key={`${row.productId}-profit`}>
                      <td>{row.name}</td>
                      <td>{row.marginPct}%</td>
                      <td>{formatCOP(row.profit)}</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={3}>Sin datos</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>
      </div>

      <div className="finance-grid-2">
        <section className="admin-dashboard-section">
          <h2 className="admin-dashboard-section__title">Margen bajo (&lt;25%)</h2>
          <div className="admin-table-wrap">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Producto</th>
                  <th>Stock</th>
                  <th>Margen</th>
                </tr>
              </thead>
              <tbody>
                {inventory.lowMarginProducts?.length ? (
                  inventory.lowMarginProducts.map((row) => (
                    <tr key={row.id}>
                      <td>{row.name}</td>
                      <td>{row.unitsInStock}</td>
                      <td className="finance-warn">{row.marginPct}%</td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={3}>Ninguno crítico</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        <section className="admin-dashboard-section">
          <h2 className="admin-dashboard-section__title">Pagos por método</h2>
          <div className="admin-table-wrap">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>Método</th>
                  <th>Pedidos</th>
                  <th>Total</th>
                </tr>
              </thead>
              <tbody>
                {paymentMethods?.map((row) => (
                  <tr key={row.method}>
                    <td>
                      {PAYMENT_METHOD_LABELS[row.method] || row.method || "—"}
                    </td>
                    <td>{row.count}</td>
                    <td>{formatCOP(row.total)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </div>

      <section className="admin-dashboard-section">
        <h2 className="admin-dashboard-section__title">
          Mayor inversión en inventario
        </h2>
        <div className="admin-table-wrap">
          <table className="admin-table">
            <thead>
              <tr>
                <th>Producto</th>
                <th>Stock</th>
                <th>Costo u.</th>
                <th>Inversión</th>
                <th>Venta pot.</th>
                <th>Ganancia pot.</th>
              </tr>
            </thead>
            <tbody>
              {inventory.catalogSummary?.map((row) => (
                <tr key={row.id}>
                  <td>{row.name}</td>
                  <td>{row.unitsInStock}</td>
                  <td>
                    {row.internalCost != null
                      ? formatCOP(row.internalCost)
                      : "—"}
                  </td>
                  <td>{formatCOP(row.investmentAtCost)}</td>
                  <td>{formatCOP(row.potentialRetail)}</td>
                  <td>{formatCOP(row.potentialProfit)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import AuthFormField from "@/components/auth/AuthFormField";
import AuthErrorAlert from "@/components/auth/AuthErrorAlert";
import ConfirmModal from "@/components/ui/ConfirmModal";
import { useFlashMessage } from "@/hooks/useFlashMessage";
import {
  getAdminHomeImages,
  createAdminHomeImage,
  updateAdminHomeImage,
  reorderAdminHomeImages,
  deleteAdminHomeImage,
} from "@/services/adminHomeImageService";
import { getCatalogFilters } from "@/services/productService";
import InspirationFocalEditor from "@/components/admin/InspirationFocalEditor";
import {
  DEFAULT_INSPIRATION_RATIO,
  frameRatio,
  inspirationLayout,
} from "@/lib/inspirationLayout";

const SECTIONS = [
  { id: "hero", label: "Hero", hint: "Varias fotografías full-bleed ordenables. La de menor orden es la principal (LCP). Se muestran en crossfade en el inicio." },
  { id: "historia", label: "Historia", hint: "Imagen del bloque origen / historia" },
  { id: "personalizacion", label: "Personalización", hint: "Imagen vertical del bloque a tu medida" },
  { id: "pormayor", label: "Por mayor", hint: "Imagen del bloque pedidos al por mayor" },
  {
    id: "coleccion",
    label: "Colecciones",
    hint: "Asocia cada imagen a un tejido. Puedes subir varias por tejido (orden = secuencia del carrusel).",
  },
  { id: "inspiracion", label: "Inspiración", hint: "Mosaico 1 grande + 4 pequeñas · máximo 5 imágenes" },
  {
    id: "editorial1",
    label: "Pausa editorial 1",
    hint: "Solo fotografía entre Descubre hoy y Personalización. 1 imagen (panorámica) o 2 (composición). Sin título ni CTA. Máx. 2.",
  },
  {
    id: "editorial2",
    label: "Pausa editorial 2",
    hint: "Solo fotografía entre Reseñas e Inspiración. 1 imagen (panorámica) o 2 (composición). Sin título ni CTA. Máx. 2.",
  },
];

const INSPIRACION_MAX = 5;
const EDITORIAL_MAX = 2;

function weaveOptionId(wt) {
  return String(wt._id || wt.id || "");
}

const INSPIRACION_UPLOAD_HELP =
  "Recomendado: foto cuadrada de 2000 × 2000 px. Deja aire alrededor del producto, especialmente arriba y abajo. Revisa el encuadre en móvil y escritorio antes de guardar.";

/** Ancho de la vista previa ≈ marco real a 1280 px (escritorio) y 390 px (móvil), a escala. */
const DESKTOP_PREVIEW = {
  lead: { width: 190, label: "protagonista" },
  secondary: { width: 146, label: "secundaria" },
  half: { width: 200, label: "media fila" },
  grid: { width: 140, label: "en fila" },
  single: { width: 200, label: "individual" },
};
const MOBILE_PREVIEW = {
  pair: { width: 104, label: "en pareja" },
  center: { width: 104, label: "centrada" },
  wide: { width: 212, label: "a lo ancho" },
  single: { width: 212, label: "individual" },
  lead: { width: 212, label: "protagonista a lo ancho" },
};

/**
 * Marcos que tendrá la foto `index` dentro de `ratios` (fotos activas en
 * orden), con las mismas reglas que la galería pública.
 */
function inspirationPreviews(ratios, index) {
  const slot = inspirationLayout(ratios)[index];
  if (!slot) return [];
  const d = DESKTOP_PREVIEW[slot.desktop.kind];
  const m = MOBILE_PREVIEW[slot.mobile.kind];
  const pos = `posición ${index + 1} de ${ratios.length}`;
  return [
    {
      key: "desktop",
      label: `Escritorio · ${d.label} · ${slot.desktop.frame || "≈ 4:5"} · ${pos}`,
      ratio: frameRatio(slot.desktop.frame),
      width: d.width,
    },
    {
      key: "mobile",
      label: `Móvil · ${m.label} · ${slot.mobile.frame}`,
      ratio: frameRatio(slot.mobile.frame),
      width: m.width,
    },
  ];
}

/**
 * Versión ligera para el editor de encuadre (misma proporción que el
 * original): los originales pueden pesar varios MB.
 */
function editorPreviewUrl(url) {
  return String(url || "").replace(
    /^(https:\/\/res\.cloudinary\.com\/[^/]+\/image\/upload\/)/,
    "$1c_limit,w_1200,q_auto,f_auto/"
  );
}

function sameFocal(a, b) {
  return (a ?? null) === (b ?? null);
}

export default function HomeImagesTab() {
  const [section, setSection] = useState("hero");
  const [images, setImages] = useState([]);
  const [weaveTypes, setWeaveTypes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [confirmModal, setConfirmModal] = useState(null);
  const { message, error, flashKey, showMsg, clearMsg } = useFlashMessage();

  const [file, setFile] = useState(null);
  const [altText, setAltText] = useState("");
  const [titulo, setTitulo] = useState("");
  const [linkHref, setLinkHref] = useState("");
  const [weaveType, setWeaveType] = useState("");

  // Encuadre (solo Inspiración)
  const [ratiosById, setRatiosById] = useState({});
  const [savedFocalById, setSavedFocalById] = useState({});
  const [newFocal, setNewFocal] = useState({ x: null, y: null });
  const [newRatio, setNewRatio] = useState(null);
  const newPreviewUrl = useMemo(
    () => (file ? URL.createObjectURL(file) : ""),
    [file]
  );
  useEffect(
    () => () => {
      if (newPreviewUrl) URL.revokeObjectURL(newPreviewUrl);
    },
    [newPreviewUrl]
  );

  const load = useCallback(async () => {
    setLoading(true);
    clearMsg();
    try {
      const [imagesData, filtersData] = await Promise.all([
        getAdminHomeImages(),
        getCatalogFilters().catch(() => null),
      ]);
      setImages(imagesData.images || []);
      setSavedFocalById(
        Object.fromEntries(
          (imagesData.images || []).map((img) => [
            img.id,
            { focalX: img.focalX ?? null, focalY: img.focalY ?? null },
          ])
        )
      );
      setWeaveTypes(filtersData?.filters?.weaveTypes || []);
    } catch (err) {
      showMsg(err.response?.data?.message || "Error al cargar imágenes", true);
    } finally {
      setLoading(false);
    }
  }, [clearMsg, showMsg]);

  useEffect(() => {
    load();
  }, [load]);

  const sectionImages = useMemo(
    () =>
      images
        .filter((img) => img.seccion === section)
        .sort((a, b) => a.orden - b.orden),
    [images, section]
  );

  const inspiracionFull =
    section === "inspiracion" && sectionImages.length >= INSPIRACION_MAX;
  const editorialFull =
    (section === "editorial1" || section === "editorial2") &&
    sectionImages.length >= EDITORIAL_MAX;
  const sectionFull = inspiracionFull || editorialFull;

  const sectionMeta = SECTIONS.find((s) => s.id === section);

  const resetForm = () => {
    setFile(null);
    setAltText("");
    setTitulo("");
    setLinkHref("");
    setWeaveType("");
    setNewFocal({ x: null, y: null });
    setNewRatio(null);
  };

  /** Fotos que verá el público (activas, en orden), con su proporción medida. */
  const ratioOf = (img) => ratiosById[img.id] || DEFAULT_INSPIRATION_RATIO;
  const previewsForCard = (img) => {
    const list = sectionImages.filter((x) => x.activo || x.id === img.id);
    return inspirationPreviews(list.map(ratioOf), list.findIndex((x) => x.id === img.id));
  };
  const previewsForNew = () => {
    const list = sectionImages.filter((x) => x.activo);
    return inspirationPreviews(
      [...list.map(ratioOf), newRatio || DEFAULT_INSPIRATION_RATIO],
      list.length
    );
  };
  const setCardFocal = (id, focalX, focalY) =>
    setImages((prev) =>
      prev.map((x) => (x.id === id ? { ...x, focalX, focalY } : x))
    );

  const applyWeaveSelection = (id, setTitle, setLink, setWeave) => {
    setWeave(id);
    const wt = weaveTypes.find((w) => weaveOptionId(w) === id);
    if (wt) {
      setTitle(wt.name || "");
      setLink(id ? `/catalogo?weaveType=${id}` : "");
    }
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!file) {
      showMsg("Selecciona una imagen desde tu dispositivo", true);
      return;
    }
    if (section === "inspiracion" && sectionImages.length >= INSPIRACION_MAX) {
      showMsg(`Inspiración admite máximo ${INSPIRACION_MAX} imágenes`, true);
      return;
    }
    if (
      (section === "editorial1" || section === "editorial2") &&
      sectionImages.length >= EDITORIAL_MAX
    ) {
      showMsg(
        `Las pausas editoriales admiten máximo ${EDITORIAL_MAX} imágenes`,
        true
      );
      return;
    }
    if (section === "coleccion" && !weaveType) {
      showMsg("Selecciona el tejido al que pertenece esta imagen", true);
      return;
    }
    setSaving(true);
    clearMsg();
    try {
      await createAdminHomeImage({
        file,
        seccion: section,
        altText,
        titulo,
        linkHref,
        weaveType: section === "coleccion" ? weaveType : undefined,
        activo: true,
        focalX: section === "inspiracion" ? newFocal.x : undefined,
        focalY: section === "inspiracion" ? newFocal.y : undefined,
      });
      showMsg("Imagen subida");
      resetForm();
      await load();
    } catch (err) {
      showMsg(err.response?.data?.message || "No se pudo subir", true);
    } finally {
      setSaving(false);
    }
  };

  const move = async (id, direction) => {
    const list = [...sectionImages];
    const idx = list.findIndex((img) => img.id === id);
    const swapIdx = idx + direction;
    if (idx < 0 || swapIdx < 0 || swapIdx >= list.length) return;

    const reordered = [...list];
    [reordered[idx], reordered[swapIdx]] = [reordered[swapIdx], reordered[idx]];
    const items = reordered.map((img, i) => ({ id: img.id, orden: i }));

    setSaving(true);
    try {
      await reorderAdminHomeImages(items);
      await load();
    } catch (err) {
      showMsg(err.response?.data?.message || "No se pudo reordenar", true);
    } finally {
      setSaving(false);
    }
  };

  const toggleActive = async (img) => {
    setSaving(true);
    try {
      await updateAdminHomeImage(img.id, { activo: !img.activo });
      await load();
    } catch (err) {
      showMsg(err.response?.data?.message || "No se pudo actualizar", true);
    } finally {
      setSaving(false);
    }
  };

  const saveMeta = async (img, patch) => {
    setSaving(true);
    try {
      await updateAdminHomeImage(img.id, patch);
      await load();
      showMsg("Guardado");
    } catch (err) {
      showMsg(err.response?.data?.message || "No se pudo guardar", true);
    } finally {
      setSaving(false);
    }
  };

  const remove = (id) => {
    setConfirmModal({
      message:
        "¿Eliminar esta imagen? También se borrará de Cloudinary si tiene publicId.",
      onConfirm: async () => {
        setConfirmModal(null);
        setSaving(true);
        try {
          await deleteAdminHomeImage(id);
          showMsg("Imagen eliminada");
          await load();
        } catch (err) {
          showMsg(err.response?.data?.message || "No se pudo eliminar", true);
        } finally {
          setSaving(false);
        }
      },
    });
  };

  if (loading) return <p className="auth-loading">Cargando…</p>;

  return (
    <div>
      <p className="admin-page__subtitle" style={{ marginTop: 0 }}>
        Sube, reordena y elimina las imágenes de cada sección del inicio
        (Cloudinary). Los textos se editan en la pestaña Inicio.
      </p>

      <ConfirmModal
        isOpen={!!confirmModal}
        message={confirmModal?.message}
        onConfirm={confirmModal?.onConfirm}
        onCancel={() => setConfirmModal(null)}
      />
      <AuthErrorAlert
        key={flashKey}
        message={message}
        variant={error ? "error" : "success"}
      />

      <nav className="cms-tabs cms-tabs--sub" aria-label="Secciones de imágenes">
        {SECTIONS.map((s) => (
          <button
            key={s.id}
            type="button"
            className={section === s.id ? "active" : ""}
            onClick={() => {
              setSection(s.id);
              clearMsg();
              resetForm();
            }}
          >
            {s.label}
          </button>
        ))}
      </nav>

      <p style={{ color: "var(--color-text-muted)", fontSize: "0.9rem" }}>
        {sectionMeta?.hint}
        {section === "inspiracion"
          ? ` · ${sectionImages.length}/${INSPIRACION_MAX}`
          : ""}
        {section === "editorial1" || section === "editorial2"
          ? ` · ${sectionImages.length}/${EDITORIAL_MAX}`
          : ""}
        {section === "hero" && sectionImages.length > 0
          ? ` · ${sectionImages.length} foto${sectionImages.length === 1 ? "" : "s"} · la primera del orden es la principal`
          : ""}
      </p>

      <form className="admin-form product-form__section" onSubmit={handleUpload}>
        <h2>Subir imagen — {sectionMeta?.label}</h2>
        {inspiracionFull ? (
          <p className="admin-page__subtitle">
            Ya hay {INSPIRACION_MAX} imágenes. Elimina una para subir otra.
          </p>
        ) : null}
        {editorialFull ? (
          <p className="admin-page__subtitle">
            Ya hay {EDITORIAL_MAX} imágenes en esta pausa. Elimina una para
            subir otra.
          </p>
        ) : null}
        <div className="auth-field">
          <label className="auth-field__label" htmlFor="home-image-file">
            Archivo (obligatorio)
          </label>
          <input
            id="home-image-file"
            type="file"
            accept="image/*"
            disabled={sectionFull || saving}
            aria-describedby={
              section === "inspiracion" ? "home-image-file-help" : undefined
            }
            onChange={(e) => {
              setFile(e.target.files?.[0] || null);
              setNewFocal({ x: null, y: null });
              setNewRatio(null);
            }}
          />
          {section === "inspiracion" ? (
            <p id="home-image-file-help" className="focal-editor__note">
              {INSPIRACION_UPLOAD_HELP}
            </p>
          ) : null}
        </div>
        {section === "inspiracion" && newPreviewUrl && !sectionFull ? (
          <InspirationFocalEditor
            src={newPreviewUrl}
            focalX={newFocal.x}
            focalY={newFocal.y}
            onChange={(x, y) => setNewFocal({ x, y })}
            onRatio={setNewRatio}
            previews={previewsForNew()}
            idPrefix="focal-new"
            disabled={saving}
          />
        ) : null}
        <AuthFormField
          label="Texto alternativo"
          name="altText"
          value={altText}
          onChange={(e) => setAltText(e.target.value)}
        />
        {section === "coleccion" && (
          <div className="auth-field">
            <label className="auth-field__label" htmlFor="coleccion-weaveType">
              Tejido (obligatorio)
            </label>
            <select
              id="coleccion-weaveType"
              className="auth-field__input"
              value={weaveType}
              disabled={saving}
              onChange={(e) =>
                applyWeaveSelection(
                  e.target.value,
                  setTitulo,
                  setLinkHref,
                  setWeaveType
                )
              }
              required
            >
              <option value="">Selecciona un tejido…</option>
              {weaveTypes.map((wt) => (
                <option key={weaveOptionId(wt)} value={weaveOptionId(wt)}>
                  {wt.name}
                </option>
              ))}
            </select>
          </div>
        )}
        {(section === "coleccion" || section === "inspiracion") && (
          <>
            <AuthFormField
              label="Título"
              name="titulo"
              value={titulo}
              onChange={(e) => setTitulo(e.target.value)}
            />
            <AuthFormField
              label="Enlace"
              name="linkHref"
              value={linkHref}
              placeholder={
                section === "coleccion"
                  ? "/catalogo?weaveType=…"
                  : "https://instagram.com/…"
              }
              onChange={(e) => setLinkHref(e.target.value)}
            />
          </>
        )}
        <div className="cms-section-actions cms-section-actions--end">
          <button
            type="submit"
            className="admin-btn admin-btn--primary"
            disabled={saving || sectionFull}
          >
            {saving ? "Subiendo…" : "Subir a Cloudinary"}
          </button>
        </div>
      </form>

      <section className="product-form__section" style={{ marginTop: "1.5rem" }}>
        <h2>Imágenes ({sectionImages.length})</h2>
        {sectionImages.length === 0 ? (
          <p className="admin-page__subtitle">
            Aún no hay imágenes en esta sección.
          </p>
        ) : (
          <div className="admin-grid-2">
            {sectionImages.map((img, idx) => (
              <article key={img.id} className="taxonomy-form-card">
                {section === "inspiracion" ? (
                  <>
                    <InspirationFocalEditor
                      src={editorPreviewUrl(img.url)}
                      focalX={img.focalX ?? null}
                      focalY={img.focalY ?? null}
                      onChange={(x, y) => setCardFocal(img.id, x, y)}
                      onRatio={(ratio) =>
                        setRatiosById((prev) =>
                          prev[img.id] === ratio
                            ? prev
                            : { ...prev, [img.id]: ratio }
                        )
                      }
                      previews={previewsForCard(img)}
                      idPrefix={`focal-${img.id}`}
                      disabled={saving}
                    />
                    {!sameFocal(img.focalX, savedFocalById[img.id]?.focalX) ||
                    !sameFocal(img.focalY, savedFocalById[img.id]?.focalY) ? (
                      <p className="focal-editor__note" role="status">
                        Encuadre sin guardar: pulsa «Guardar datos».
                      </p>
                    ) : null}
                  </>
                ) : (
                  <img
                    src={img.url}
                    alt={img.altText || img.titulo || "Home"}
                    loading="lazy"
                    decoding="async"
                    style={{
                      width: "100%",
                      height: 160,
                      objectFit: "cover",
                      borderRadius: 4,
                      border: "1px solid var(--color-border)",
                    }}
                  />
                )}
                <p
                  style={{
                    fontSize: "0.8rem",
                    color: "var(--color-text-muted)",
                  }}
                >
                  {section === "hero" ? (
                    <>
                      <strong style={{ color: "var(--color-text)" }}>
                        {String(idx + 1).padStart(2, "0")}
                      </strong>
                      {idx === 0 ? " · Principal (LCP) · " : " · "}
                    </>
                  ) : null}
                  Orden {img.orden} · {img.activo ? "Activa" : "Inactiva"}
                  {img.weaveTypeId
                    ? ` · tejido ${
                        weaveTypes.find(
                          (w) => weaveOptionId(w) === img.weaveTypeId
                        )?.name || img.weaveTypeId
                      }`
                    : ""}
                </p>
                <div className="auth-field">
                  <label className="auth-field__label">Alt</label>
                  <input
                    className="auth-field__input"
                    value={img.altText || ""}
                    onChange={(e) =>
                      setImages((prev) =>
                        prev.map((x) =>
                          x.id === img.id
                            ? { ...x, altText: e.target.value }
                            : x
                        )
                      )
                    }
                  />
                </div>
                {section === "coleccion" && (
                  <div className="auth-field">
                    <label className="auth-field__label">Tejido</label>
                    <select
                      className="auth-field__input"
                      value={img.weaveTypeId || ""}
                      onChange={(e) => {
                        const id = e.target.value;
                        const wt = weaveTypes.find(
                          (w) => weaveOptionId(w) === id
                        );
                        setImages((prev) =>
                          prev.map((x) =>
                            x.id === img.id
                              ? {
                                  ...x,
                                  weaveTypeId: id || null,
                                  titulo: wt?.name || x.titulo,
                                  linkHref: id
                                    ? `/catalogo?weaveType=${id}`
                                    : x.linkHref,
                                }
                              : x
                          )
                        );
                      }}
                    >
                      <option value="">Sin asociar…</option>
                      {weaveTypes.map((wt) => (
                        <option
                          key={weaveOptionId(wt)}
                          value={weaveOptionId(wt)}
                        >
                          {wt.name}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
                {(section === "coleccion" || section === "inspiracion") && (
                  <>
                    <div className="auth-field">
                      <label className="auth-field__label">Título</label>
                      <input
                        className="auth-field__input"
                        value={img.titulo || ""}
                        onChange={(e) =>
                          setImages((prev) =>
                            prev.map((x) =>
                              x.id === img.id
                                ? { ...x, titulo: e.target.value }
                                : x
                            )
                          )
                        }
                      />
                    </div>
                    <div className="auth-field">
                      <label className="auth-field__label">Enlace</label>
                      <input
                        className="auth-field__input"
                        value={img.linkHref || ""}
                        onChange={(e) =>
                          setImages((prev) =>
                            prev.map((x) =>
                              x.id === img.id
                                ? { ...x, linkHref: e.target.value }
                                : x
                            )
                          )
                        }
                      />
                    </div>
                  </>
                )}
                <div style={{ display: "flex", flexWrap: "wrap", gap: "0.5rem" }}>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm"
                    disabled={saving}
                    onClick={() =>
                      saveMeta(img, {
                        altText: img.altText || "",
                        titulo: img.titulo || "",
                        linkHref: img.linkHref || "",
                        weaveType:
                          section === "coleccion"
                            ? img.weaveTypeId || null
                            : undefined,
                        ...(section === "inspiracion"
                          ? {
                              focalX: img.focalX ?? null,
                              focalY: img.focalY ?? null,
                            }
                          : {}),
                      })
                    }
                  >
                    Guardar datos
                  </button>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm"
                    disabled={saving || idx === 0}
                    onClick={() => move(img.id, -1)}
                  >
                    Subir
                  </button>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm"
                    disabled={saving || idx === sectionImages.length - 1}
                    onClick={() => move(img.id, 1)}
                  >
                    Bajar
                  </button>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm"
                    disabled={saving}
                    onClick={() => toggleActive(img)}
                  >
                    {img.activo ? "Desactivar" : "Activar"}
                  </button>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm admin-btn--danger"
                    disabled={saving}
                    onClick={() => remove(img.id)}
                  >
                    Eliminar
                  </button>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

"use client";
import { Suspense, useEffect, useRef, useState } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import OrderCommunications from "./OrderCommunications";
import OrderNextAction from "./OrderNextAction";
import { useSiteConfig } from "@/context/SiteConfigContext";
import { getAdminOrder, updateOrderStatus, confirmPayment, reconcileWompi, updateOrderShipping } from "@/services/orderAdminService";
import { formatCOP } from "@/lib/formatCurrency";
import { ORDER_STATUS_LABELS, PAYMENT_STATUS_LABELS, PAYMENT_METHOD_LABELS, CARRIER_LABELS } from "@/lib/orderLabels";
import { formatOrderDate, returnToOrders } from "@/lib/orderWorkspace";
import styles from "./OrderWorkspace.module.css";
export default function OrderDetail(props) {
  return <Suspense fallback={<p role="status">Cargando pedido…</p>}><OrderWorkspaceDetail {...props} /></Suspense>;
}
function OrderWorkspaceDetail({ orderId, backHref = "/admin/pedidos" }) {
  const params = useSearchParams();
  const { siteName } = useSiteConfig();
  const back = returnToOrders(params.get("returnTo"), backHref);
  const [version, setVersion] = useState(0);
  const key = `${orderId}:${version}`;
  const [state, setState] = useState(null);
  const [busy, setBusy] = useState(false);
  const [locked, setLocked] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [communicationsVersion, setCommunicationsVersion] = useState(0);
  const inFlightRef = useRef(false);
  useEffect(() => {
    let active = true;
    getAdminOrder(orderId).then((result) => {
      if (active) { setState({ key, order: result.order }); setLocked(false); }
    }).catch((err) => { if (active) setState({ key, error: err.response?.status === 404 ? "No se encontró este pedido." : "No se pudo cargar el pedido. Inténtalo de nuevo." }); });
    return () => { active = false; };
  }, [key, orderId]);
  const loading = state?.key !== key;
  const order = !loading && state?.order;
  const loadError = !loading && state?.error;
  const execute = async (code, values) => {
    if (inFlightRef.current || locked) return false;
    inFlightRef.current = true; setBusy(true); setError(""); setMessage("");
    let recorded = false;
    try {
      if (code === "collect") await confirmPayment(orderId, values);
      else if (code === "reconcile") await reconcileWompi(orderId);
      else if (["dispatch", "correct"].includes(code)) await updateOrderShipping(orderId, values);
      else {
        const status = { prepare: "en_preparacion", deliver: "entregado", cancel: "cancelado", return: "devuelto" }[code];
        if (!status) throw new Error("Acción no disponible");
        await updateOrderStatus(orderId, { orderStatus: status, note: values.note || "" });
      }
      recorded = true;
      const result = await getAdminOrder(orderId);
      setState({ key, order: result.order });
      setCommunicationsVersion((v) => v + 1);
      setMessage(code === "collect" ? "Recaudo verificado en el registro. El despacho y la entrega no se modificaron." : code === "reconcile" ? "Consulta completada. Revisa el estado y las incidencias resultantes." : "Operación registrada. La siguiente acción y las comunicaciones se actualizaron.");
      return true;
    } catch (err) {
      const uncertain = recorded || !err.response || err.response.status >= 500;
      if (uncertain) setLocked(true);
      setError(recorded ? "La operación se registró, pero no se pudo actualizar la pantalla. Actualiza el pedido antes de continuar." : err.response?.data?.message || "No se pudo confirmar el resultado. Actualiza el pedido antes de volver a intentarlo.");
      return false;
    } finally { inFlightRef.current = false; setBusy(false); }
  };
  const refresh = () => { setError(""); setVersion((v) => v + 1); };
  const phone = (order?.buyer?.phone || "").replace(/\D/g, "");
  const waPhone = phone.length === 10 ? `57${phone}` : phone;
  const whatsappText = order ? encodeURIComponent(`Hola ${order.buyer?.name}, tu pedido ${order.orderNumber} en ${siteName} está ${ORDER_STATUS_LABELS[order.orderStatus] || order.orderStatus}.`) : "";
  return <div className={styles.workspace}>
    <div className={styles.header}><Link href={back}>← Volver a pedidos</Link><button type="button" className="admin-btn" disabled={busy || loading} onClick={refresh}>Actualizar pedido</button></div>
    {loading && <p role="status" className={styles.notice}>Cargando pedido…</p>}
    {loadError && <div className={`${styles.notice} ${styles.error}`} role="alert"><p>{loadError}</p><button type="button" className="admin-btn" onClick={refresh}>Reintentar carga</button></div>}
    {message && <p role="status" className={`${styles.notice} ${styles.success}`}>{message}</p>}
    {error && <p role="alert" className={`${styles.notice} ${styles.error}`}>{error}</p>}
    {order && <>
      <header><p className={styles.eyebrow}>Pedido · {formatOrderDate(order.createdAt)}</p><h1>{order.orderNumber}</h1><div className={styles.summary}><span className={styles.badge}>{ORDER_STATUS_LABELS[order.orderStatus] || order.orderStatus}</span><span>Pago: {PAYMENT_STATUS_LABELS[order.paymentStatus] || order.paymentStatus}</span><span>{PAYMENT_METHOD_LABELS[order.paymentMethod] || order.paymentMethod}</span><strong>{formatCOP(order.total)}</strong>{order.operation?.requiresReview && <span className={`${styles.badge} ${styles.attention}`}>Requiere revisión</span>}</div></header>
      <OrderNextAction key={`${orderId}:${order.orderStatus}:${order.paymentStatus}`} order={order} execute={execute} busy={busy} locked={locked} />
      <div className={styles.detail}>
        <div className={styles.stack}>
          <section className={styles.panel}><h2>Productos · {order.items?.length || 0}</h2><ul className={styles.list}>{(order.items || []).map((item, index) => <li key={item._id || index}><div className={styles.product}>{item.productImage && <img src={item.productImage} alt="" loading="lazy" decoding="async" />}<div><strong>{item.productName}</strong><p className={styles.muted}>{[item.sizeName, item.colorName, item.sku].filter(Boolean).join(" · ")}</p><p>{item.quantity} × {formatCOP(item.unitPrice)} · <strong>{formatCOP(item.lineTotal)}</strong></p></div></div></li>)}</ul>
            <dl className={styles.rows}><dt>Subtotal</dt><dd>{formatCOP(order.subtotal)}</dd>{order.ivaEnabled && <><dt>IVA {order.ivaPercent || ""}%</dt><dd>{formatCOP(order.taxTotal)}</dd></>}<dt>Envío</dt><dd>{order.shippingIncluded ? "Incluido en el precio" : order.freeShippingApplied ? "Gratis (promoción anterior)" : formatCOP(order.shippingCost)}</dd><dt>Cupón</dt><dd>{order.couponCode ? `${order.couponCode} · −${formatCOP(order.discountTotal)}` : "Sin cupón"}</dd><dt>Total del pedido</dt><dd><strong>{formatCOP(order.total)}</strong></dd></dl>
          </section>
          <section className={styles.panel}><h2>Historial del pedido</h2>{order.statusHistory?.length ? <ol className={styles.list}>{[...order.statusHistory].reverse().map((entry, index) => <li key={entry._id || index}><strong>{ORDER_STATUS_LABELS[entry.status] || entry.status}</strong>{entry.note && <p>{entry.note}</p>}<small className={styles.muted}>{formatOrderDate(entry.changedAt)}</small></li>)}</ol> : <p>No hay cambios registrados en el historial disponible.</p>}</section>
          <OrderCommunications key={`${orderId}:${communicationsVersion}`} orderId={orderId} />
        </div>
        <div className={styles.stack}>
          <section className={styles.panel}><h2>Cliente y entrega</h2><p><strong>{order.buyer?.name}</strong></p><p>{order.buyer?.email}</p><p>{order.buyer?.phone}</p><p>{[order.shippingAddress?.address, order.shippingAddress?.city, order.shippingAddress?.department].filter(Boolean).join(", ")}</p>{order.customerNotes && <p>Nota del cliente: {order.customerNotes}</p>}{waPhone && <div className={styles.actions}><a href={`https://wa.me/${waPhone}?text=${whatsappText}`} target="_blank" rel="noopener noreferrer" className="admin-btn">Abrir conversación en WhatsApp</a></div>}<p className={styles.muted}>Abrir la conversación no envía un mensaje.</p></section>
          <section className={styles.panel}><h2>Datos del envío</h2><dl className={styles.rows}><dt>Transportadora</dt><dd>{CARRIER_LABELS[order.carrier] || order.carrier || "Sin asignar"}</dd><dt>Guía</dt><dd>{order.trackingNumber || "Sin registrar"}</dd><dt>Entrega registrada</dt><dd>{order.deliveredAt ? formatOrderDate(order.deliveredAt) : "Sin fecha verificada"}</dd></dl>{order.shippingNotes && <p>Nota interna: {order.shippingNotes}</p>}</section>
          <section className={styles.panel}><h2>Información de pago</h2><p>{PAYMENT_METHOD_LABELS[order.paymentMethod]} · {PAYMENT_STATUS_LABELS[order.paymentStatus]}</p>{order.collection?.reference && <p>Referencia de recaudo: {order.collection.reference} · {formatOrderDate(order.collection.receivedAt)}</p>}{order.paymentProofUrl && <p>Comprobante registrado: {order.paymentProofUrl}</p>}{order.wompi?.transactionId && <p>Transacción Wompi: {order.wompi.transactionId}</p>}{order.wompi?.expiresAt && <p>Vigencia del enlace: {formatOrderDate(order.wompi.expiresAt)}</p>}{order.operation?.reasons?.map((reason, index) => <p key={index} className={styles.notice}>{reason}</p>)}{order.incidents?.filter((i) => !i.resolvedAt).map((i, index) => <p key={i._id || index} className={styles.muted}>{i.detail}</p>)}{order.incidents?.some((i) => i.resolvedAt) && <details><summary>Incidencias resueltas</summary>{order.incidents.filter((i) => i.resolvedAt).map((i, index) => <p key={i._id || index}>Registro conciliado · {formatOrderDate(i.resolvedAt)}{i.detail && ` · ${i.detail}`}</p>)}</details>}</section>
        </div>
      </div>
    </>}
  </div>;
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import {
  adjustProductStock,
  createAdminProduct,
  getCatalogMeta,
  getAdminProduct,
  updateAdminProduct,
  uploadProductImages,
  uploadTempImages,
} from "@/services/adminCatalogService";

const newClientKey = () =>
  `v-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

const emptyVariant = () => ({
  clientKey: newClientKey(),
  id: null,
  size: "",
  color: "",
  sku: "",
  stock: 0,
  price: "",
  isActive: true,
});

const DIACRITICS_RE = new RegExp("[\\u0300-\\u036f]", "g");

const generateSeed = () =>
  Math.random().toString(36).substring(2, 6).toUpperCase();

const extractSeedFromSku = (sku) => {
  const match = /^[A-Z0-9]{1,4}-([A-Z0-9]{4})-\d{2,}$/i.exec(sku || "");
  return match ? match[1].toUpperCase() : null;
};

const skuPrefixFromName = (productName) =>
  (productName || "")
    .normalize("NFD")
    .replace(DIACRITICS_RE, "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .substring(0, 3)
    .toUpperCase() || "PRD";

const parseSkuSeq = (sku, seed) => {
  const match = new RegExp(`^[A-Z0-9]{1,4}-${seed}-(\\d{2,})$`, "i").exec(
    sku || ""
  );
  return match ? Number.parseInt(match[1], 10) : null;
};

const usedSkuSet = (variants) =>
  new Set(
    (variants || [])
      .map((v) => String(v.sku || "").trim().toUpperCase())
      .filter(Boolean)
  );

const generateUniqueSku = (productName, seed, variants) => {
  const prefix = skuPrefixFromName(productName);
  const existing = usedSkuSet(variants);
  let seq = 0;
  for (const v of variants || []) {
    const n = parseSkuSeq(v.sku, seed);
    if (n != null && n > seq) seq = n;
  }
  seq += 1;
  let sku = `${prefix}-${seed}-${String(seq).padStart(2, "0")}`;
  while (existing.has(sku)) {
    seq += 1;
    sku = `${prefix}-${seed}-${String(seq).padStart(2, "0")}`;
  }
  return sku;
};

const defaultForm = () => ({
  name: "",
  shortDescription: "",
  fullDescription: "",
  category: "",
  weaveType: "",
  style: "",
  material: "Palma de iraca",
  salePrice: "",
  internalCost: "",
  discountPercent: 0,
  onPromotion: false,
  isActive: true,
  isFeatured: false,
  isNew: false,
  allowsCustomization: false,
  seoTitle: "",
  seoDescription: "",
  images: [],
  mainImage: "",
  variants: [emptyVariant()],
});

export default function ProductForm({ productId, returnTo = "/admin/productos" }) {
  const router = useRouter();
  const isEdit = Boolean(productId);

  // Semilla estable por montaje (estado, no ref: se lee durante el render inicial).
  const [initialSkuSeed] = useState(generateSeed);
  const skuSeedRef = useRef(initialSkuSeed);

  const saveRef = useRef(false), savedRef = useRef(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [loadAttempt, setLoadAttempt] = useState(0);
  const [meta, setMeta] = useState(null);
  const [form, setForm] = useState(() => {
    const initial = defaultForm();
    initial.variants[0].sku = generateUniqueSku("", initialSkuSeed, []);
    return initial;
  });
  const [newImageUrl, setNewImageUrl] = useState("");
  const [loading, setLoading] = useState(isEdit);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadingCount, setUploadingCount] = useState(0);
  const [error, setError] = useState("");
  const [adjustmentStates, setAdjustmentStates] = useState({});
  // Refs are updated synchronously: a second click in the same render sees
  // the pending operation, including its immutable payload and idempotency key.
  const inFlightAdjustmentsRef = useRef(new Map());

  const MAX_IMAGES = 10;
  const MAX_BATCH = 3;

  useEffect(() => {
    const load = async () => {
      try {
        const metaRes = await getCatalogMeta();
        setMeta(metaRes.meta);

        if (isEdit) {
          const { product } = await getAdminProduct(productId);
          setForm({
            name: product.name || "",
            shortDescription: product.shortDescription || "",
            fullDescription: product.fullDescription || "",
            category:
              product.category?._id ||
              product.category?.id ||
              product.category ||
              "",
            weaveType:
              product.weaveType?._id ||
              product.weaveType?.id ||
              product.weaveType ||
              "",
            style:
              product.style?._id ||
              product.style?.id ||
              product.style ||
              "",
            material: product.material || "Palma de iraca",
            salePrice: product.salePrice ?? "",
            internalCost: product.internalCost ?? "",
            discountPercent: product.discountPercent ?? 0,
            onPromotion: Boolean(product.onPromotion),
            isActive: product.isActive !== false,
            isFeatured: Boolean(product.isFeatured),
            isNew: Boolean(product.isNew),
            allowsCustomization: Boolean(product.allowsCustomization),
            seoTitle: product.seoTitle || "",
            seoDescription: product.seoDescription || "",
            images: (product.images || []).map((img) => ({
              url: img.url,
              publicId: img.publicId || null,
              alt: img.alt || product.name,
            })),
            mainImage: product.mainImage || "",
            variants:
              product.variants?.length > 0
                ? product.variants.map((v) => ({
                    clientKey: String(v.id || v._id || newClientKey()),
                    id: v.id || v._id || null,
                    size: v.size?.toString?.() || v.size || "",
                    color: v.color?.toString?.() || v.color || "",
                    sku: v.sku || "",
                    stock: v.stock ?? "",
                    price: v.price ?? "",
                    isActive: v.isActive !== false,
                  }))
                : [],
          });
          const firstSku = product.variants?.[0]?.sku;
          const extracted = extractSeedFromSku(firstSku);
          if (extracted) skuSeedRef.current = extracted;
        }
      } catch (err) {
        setError(err.response?.data?.message || "Error al cargar datos"); setLoadFailed(true);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [productId, isEdit, loadAttempt]);

  const setField = (key, value) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const setVariant = (index, key, value) => {
    setForm((prev) => {
      const variants = [...prev.variants];
      variants[index] = { ...variants[index], [key]: value };
      return { ...prev, variants };
    });
  };

  const handleNameChange = (value) => {
    setForm((prev) => {
      if (isEdit) return { ...prev, name: value };
      const seed = skuSeedRef.current;
      const assigned = [];
      const variants = prev.variants.map((v) => {
        const next = {
          ...v,
          sku: generateUniqueSku(value, seed, assigned),
        };
        assigned.push(next);
        return next;
      });
      return { ...prev, name: value, variants };
    });
  };

  const addVariant = () => {
    setForm((prev) => {
      const next = {
        ...emptyVariant(),
        sku: generateUniqueSku(prev.name, skuSeedRef.current, prev.variants),
      };
      return { ...prev, variants: [...prev.variants, next] };
    });
  };

  const removeVariant = (index) => {
    setForm((prev) => {
      if (prev.variants.length <= 1) return prev;
      return {
        ...prev,
        variants: prev.variants[index]?.id ? prev.variants.map((v, i) => i === index ? { ...v, isActive: false } : v) : prev.variants.filter((_, i) => i !== index),
      };
    });
  };

  const addImage = () => {
    const url = newImageUrl.trim();
    if (!url) return;
    setForm((prev) => {
      const images = [...prev.images, { url, alt: prev.name || "Producto" }];
      return {
        ...prev,
        images,
        mainImage: prev.mainImage || url,
      };
    });
    setNewImageUrl("");
  };

  const MAX_FILE_BYTES = 10 * 1024 * 1024;

  const validateFiles = (files) => {
    if (files.length > MAX_BATCH)
      return `Selecciona máximo ${MAX_BATCH} imágenes por subida`;
    const oversized = files.find((f) => f.size > MAX_FILE_BYTES);
    if (oversized)
      return `"${oversized.name}" supera el límite de peso de 10 MB. Reduce el tamaño o usa otra imagen.`;
    return null;
  };

  const handleFileUpload = async (e) => {
    const files = Array.from(e.target.files || []);
    e.target.value = "";
    if (!files.length) return;

    const validationError = validateFiles(files);
    if (validationError) {
      setError(validationError);
      return;
    }

    const remaining = MAX_IMAGES - form.images.length;
    if (files.length > remaining) {
      setError(
        remaining === 0
          ? "El producto ya tiene el máximo de 10 imágenes"
          : `Solo puedes agregar ${remaining} imagen${remaining !== 1 ? "es" : ""} más (máximo ${MAX_IMAGES})`
      );
      return;
    }

    setUploadingCount(files.length);
    setUploading(true);
    setError("");
    try {
      if (productId) {
        const data = await uploadProductImages(productId, files);
        setForm((prev) => ({
          ...prev,
          images: data.images || prev.images,
          mainImage: data.mainImage || prev.mainImage,
        }));
      } else {
        const data = await uploadTempImages(files);
        const newImages = data.images || [];
        setForm((prev) => {
          const combined = [...prev.images, ...newImages];
          return {
            ...prev,
            images: combined,
            mainImage: prev.mainImage || newImages[0]?.url || "",
          };
        });
      }
    } catch (err) {
      setError(err.response?.data?.message || "Error al subir imágenes");
    } finally {
      setUploading(false);
      setUploadingCount(0);
    }
  };

  const removeImage = (index) => {
    setForm((prev) => {
      const images = prev.images.filter((_, i) => i !== index);
      let mainImage = prev.mainImage;
      if (!images.find((img) => img.url === mainImage)) {
        mainImage = images[0]?.url || "";
      }
      return { ...prev, images, mainImage };
    });
  };

  const setMainImage = (url) => {
    setField("mainImage", url);
  };

  const buildPayload = () => ({
    name: form.name.trim(),
    shortDescription: form.shortDescription.trim(),
    fullDescription: form.fullDescription.trim(),
    category: form.category,
    weaveType: form.weaveType || null,
    style: form.style || null,
    material: form.material.trim() || "Palma de iraca",
    salePrice: Number(form.salePrice),
    internalCost:
      form.internalCost === "" ? undefined : Number(form.internalCost),
    discountPercent: Number(form.discountPercent) || 0,
    onPromotion: form.onPromotion,
    isActive: form.isActive,
    isFeatured: form.isFeatured,
    isNew: form.isNew,
    allowsCustomization: form.allowsCustomization,
    seoTitle: form.seoTitle.trim() || form.name.trim(),
    seoDescription: form.seoDescription.trim(),
    images: form.images.map((img) => ({
      url: img.url,
      publicId: img.publicId || null,
      alt: img.alt || form.name,
    })),
    mainImage: form.mainImage || form.images[0]?.url,
    variants: form.variants.map((v) => ({
      ...(v.id ? { id: v.id } : {}),
      size: v.size || null,
      color: v.color || null,
      sku: String(v.sku).trim().toUpperCase(),
      ...(!v.id ? { stock: Number(v.stock) || 0 } : {}),
      price:
        v.price === "" || v.price == null ? null : Number(v.price),
      isActive: v.isActive !== false,
    })),
  });

  const handleStockAdjustment = async (index) => {
    const variant = form.variants[index];
    if (!variant?.id) return;
    const operations = inFlightAdjustmentsRef.current;
    let operation = operations.get(variant.id);
    if (operation?.inFlight || operation?.completed) return;
    const delta = Number(variant.adjustmentDelta);
    if (!Number.isSafeInteger(delta) || delta === 0 || !variant.adjustmentReason?.trim()) { setError("Registra una cantidad entera distinta de cero y el motivo del ajuste"); return; }
    if (!operation) {
      operation = { payload: { variantId: variant.id, delta,
        reason: variant.adjustmentReason.trim(), operationKey: crypto.randomUUID() } };
      operations.set(variant.id, operation);
    }
    operation.inFlight = true;
    setAdjustmentStates((prev) => ({ ...prev, [variant.id]: { status: "processing", message: "Registrando ajuste…" } }));
    try {
      const result = await adjustProductStock(productId, operation.payload);
      operation.completed = true;
      setForm((prev) => ({ ...prev, variants: prev.variants.map((v) => v.id === variant.id
        ? { ...v, stock: result.currentStock ?? result.stock, adjustmentDelta: "", adjustmentReason: "" } : v) }));
      setAdjustmentStates((prev) => ({ ...prev, [variant.id]: { status: "success", message: `Ajuste registrado. Stock: ${result.currentStock ?? result.stock}.` } }));
      setError("");
    } catch (err) {
      const status = err.response?.status;
      // Explicit business rejections permit correcting the form. Ambiguous
      // network/5xx errors retain the original key AND payload for a safe retry.
      const retryPending = ![400, 403, 404, 409, 422].includes(status);
      if (!retryPending) operations.delete(variant.id);
      const message = err.response?.data?.message || "No se pudo confirmar el ajuste. Reintenta la misma operación.";
      setAdjustmentStates((prev) => ({ ...prev, [variant.id]: { status: "error", message, retryPending } }));
    } finally {
      operation.inFlight = false;
    }
  };

  const setAdjustmentField = (index, key, value) => {
    const variant = form.variants[index];
    const operation = inFlightAdjustmentsRef.current.get(variant.id);
    if (operation?.inFlight || (operation && !operation.completed)) return;
    inFlightAdjustmentsRef.current.delete(variant.id);
    setAdjustmentStates((prev) => ({ ...prev, [variant.id]: null }));
    setVariant(index, key, value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (saveRef.current || savedRef.current) return;
    saveRef.current = true;
    setSaving(true);
    setError("");

    if (!form.images.length) {
      setError("Agrega al menos una imagen antes de guardar");
      setSaving(false); saveRef.current = false;
      return;
    }

    if (!form.category) {
      setError("Selecciona la categoría");
      setSaving(false); saveRef.current = false;
      return;
    }

    const skus = form.variants.map((v) =>
      String(v.sku || "").trim().toUpperCase()
    );
    if (skus.some((sku) => !sku)) {
      setError("Cada variante necesita un SKU");
      setSaving(false); saveRef.current = false;
      return;
    }
    if (new Set(skus).size !== skus.length) {
      setError("Hay SKUs duplicados. Cada variante debe tener un código único.");
      setSaving(false); saveRef.current = false;
      return;
    }
    const combos = form.variants.filter((v) => v.isActive !== false).map((v) => `${v.size || ""}|${v.color || ""}`);
    if (new Set(combos).size !== combos.length) {
      setError("Hay variantes con la misma talla y color");
      setSaving(false); saveRef.current = false;
      return;
    }

    try {
      const payload = buildPayload();
      if (isEdit) {
        await updateAdminProduct(productId, payload);
        savedRef.current = true; router.push(returnTo);
      } else {
        await createAdminProduct(payload);
        savedRef.current = true; router.push(returnTo);
      }
    } catch (err) {
      setError(
        err.response?.data?.message ||
          err.response?.data?.error?.message ||
          "No se pudo guardar el producto"
      );
    } finally {
      setSaving(false); saveRef.current = false;
    }
  };

  if (loading) {
    return <p className="auth-loading">Cargando producto…</p>;
  }

  if (loadFailed) return <div role="alert"><p>{error}</p><button type="button" className="admin-btn" onClick={() => { setLoadFailed(false); setLoading(true); setLoadAttempt((n) => n + 1); }}>Reintentar carga del producto</button><Link href={returnTo}>Volver a productos</Link></div>;

  const categories = meta?.categories || [];
  const colors = meta?.colors || [];
  const sizes = meta?.sizes || [];
  // Solo opciones activas (más la ya asignada, para no perderla al editar).
  const usable = (list, current) =>
    (list || []).filter((i) => i.isActive !== false || i._id === current);
  const weaveTypes = usable(meta?.weaveTypes, form.weaveType);
  const styles = usable(meta?.styles, form.style);

  const skuDupSet = new Set();
  const comboDupSet = new Set();
  {
    const skuCount = {};
    const comboCount = {};
    form.variants.forEach((v) => {
      const sku = String(v.sku || "").trim().toUpperCase();
      if (sku) skuCount[sku] = (skuCount[sku] || 0) + 1;
      if (v.isActive !== false) {
        const combo = `${v.size || ""}|${v.color || ""}`;
        comboCount[combo] = (comboCount[combo] || 0) + 1;
      }
    });
    Object.entries(skuCount).forEach(([sku, n]) => {
      if (n > 1) skuDupSet.add(sku);
    });
    Object.entries(comboCount).forEach(([combo, n]) => {
      if (n > 1) comboDupSet.add(combo);
    });
  }

  return (
    <form className="product-form admin-form" onSubmit={handleSubmit}>
      {error && <p role="alert" className="admin-form-error">{error}</p>}

      <div className="product-form__navigation"><Link href={returnTo}>← Volver a la lista filtrada</Link><nav aria-label="Secciones del producto"><a href="#product-general">Información</a><a href="#product-images">Imágenes</a><a href="#product-price">Precio y promoción</a><a href="#product-variants">Variantes</a><a href="#product-publication">Publicación</a></nav></div>
      <p className="product-form__hint">
        Configura taxonomías en{" "}
        <Link href="/admin/catalogo">Catálogo base</Link> si faltan opciones.
      </p>

      <section id="product-general" className="product-form__section">
        <h2>Información general</h2>
        <div className="admin-form__row">
          <div className="admin-form__group admin-form__group--wide">
            <label htmlFor="name">Nombre *</label>
            <input
              id="name"
              value={form.name}
              onChange={(e) => handleNameChange(e.target.value)}
              required
            />
          </div>
          <div className="admin-form__group">
            <label htmlFor="material">Material</label>
            <input
              id="material"
              value={form.material}
              onChange={(e) => setField("material", e.target.value)}
            />
          </div>
        </div>

        <div className="admin-form__group">
          <label htmlFor="shortDescription">Descripción corta</label>
          <textarea
            id="shortDescription"
            rows={2}
            value={form.shortDescription}
            onChange={(e) => setField("shortDescription", e.target.value)}
          />
        </div>
        <div className="admin-form__group">
          <label htmlFor="fullDescription">Descripción completa</label>
          <textarea
            id="fullDescription"
            rows={12}
            value={form.fullDescription}
            onChange={(e) => setField("fullDescription", e.target.value)}
            placeholder={`Ejemplo:

Sombrero tejido a mano en palma de iraca.

# Material y origen
Fibra natural de Sandoná, Nariño.

# Detalles
- Ala flexible
- Acabado a mano
- Ideal para clima cálido

![Detalle del tejido](https://res.cloudinary.com/.../detalle.jpg)`}
          />
          <p className="image-upload-hint">
            Formato: línea en blanco = nuevo bloque.{" "}
            <code># Título</code> o <code>#Título</code> se muestra en
            mayúsculas y negrita (sin el #).{" "}
            <code>- texto</code> = viñeta con sangría. Enter = salto de línea.{" "}
            <code>![texto alt](url)</code> = imagen (el texto entre{" "}
            <code>[]</code> no se ve en pantalla, solo ayuda a accesibilidad).
            Las fotos principales van en la galería del producto.
          </p>
        </div>

        <div className="admin-form__row">
          <div className="admin-form__group">
            <label htmlFor="category">Categoría *</label>
            <select
              id="category"
              value={form.category}
              onChange={(e) => setField("category", e.target.value)}
              required
            >
              <option value="">Seleccionar…</option>
              {categories.map((c) => (
                <option key={c._id} value={c._id}>
                  {c.name}
                </option>
              ))}
            </select>
          </div>
          <div className="admin-form__group">
            <label htmlFor="weaveType">Tejido</label>
            <select
              id="weaveType"
              value={form.weaveType}
              onChange={(e) => setField("weaveType", e.target.value)}
            >
              <option value="">No aplica</option>
              {weaveTypes.map((w) => (
                <option key={w._id} value={w._id}>
                  {w.name}
                </option>
              ))}
            </select>
          </div>
          <div className="admin-form__group">
            <label htmlFor="style">Estilo / horma</label>
            <select
              id="style"
              value={form.style}
              onChange={(e) => setField("style", e.target.value)}
            >
              <option value="">No aplica</option>
              {styles.map((s) => (
                <option key={s._id} value={s._id}>
                  {s.name}
                </option>
              ))}
            </select>
          </div>
        </div>
        <p className="image-upload-hint">
          Tejido y horma describen sombreros: en bolsos o accesorios deja
          «No aplica» en lo que no corresponda (no uses el nombre de la
          categoría como horma). Así los filtros del catálogo muestran solo
          opciones reales.
        </p>
      </section>

<section id="product-images" className="product-form__section">
        <h2>
          Imágenes
          <span
            className={`image-count-badge${form.images.length >= MAX_IMAGES ? " image-count-badge--full" : ""}`}
          >
            {form.images.length} / {MAX_IMAGES}
          </span>
        </h2>

        {meta?.cloudinaryConfigured ? (
          <div className="image-upload-block">
            <label
              className={`admin-btn admin-btn--sm image-upload-label${uploading ? " is-uploading" : ""}`}
            >
              {uploading ? (
                <>
                  <span className="upload-spinner" aria-hidden="true" />
                  Subiendo {uploadingCount} imagen{uploadingCount !== 1 ? "es" : ""}…
                </>
              ) : (
                "Subir desde equipo"
              )}
              <input
                type="file"
                accept="image/*"
                multiple
                hidden
                disabled={uploading || form.images.length >= MAX_IMAGES}
                onChange={handleFileUpload}
              />
            </label>
            <p className="image-upload-hint">
              Máx. {MAX_BATCH} archivos por subida · 10 MB c/u · JPG, PNG, WebP
            </p>
          </div>
        ) : (
          <p className="image-upload-hint image-upload-hint--info">
            La carga de archivos no está disponible en este entorno. Puedes agregar imágenes por enlace o consultar al responsable de configuración.
          </p>
        )}

        <div className="image-section-divider">
          <span>o agrega por enlace</span>
        </div>

        <div className="image-url-add">
          <input
            type="url"
            aria-label="URL de imagen"
            placeholder="https://… URL de imagen"
            value={newImageUrl}
            onChange={(e) => setNewImageUrl(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                addImage();
              }
            }}
          />
          <button
            type="button"
            className="admin-btn"
            onClick={addImage}
            disabled={form.images.length >= MAX_IMAGES}
          >
            Agregar
          </button>
        </div>

        {form.images.length > 0 && (
          <ul className="image-list">
            {form.images.map((img, index) => (
              <li key={`${img.url}-${index}`}>
                <img
                  src={img.url}
                  alt={img.alt}
                  width={72}
                  height={72}
                  loading="lazy"
                  decoding="async"
                />
                <div className="image-list__meta">
                  <button
                    type="button"
                    className={
                      form.mainImage === img.url
                        ? "admin-btn admin-btn--sm admin-btn--primary"
                        : "admin-btn admin-btn--sm"
                    }
                    onClick={() => setMainImage(img.url)}
                  >
                    {form.mainImage === img.url ? "Principal" : "Hacer principal"}
                  </button>
                  <button
                    type="button"
                    className="admin-btn admin-btn--sm admin-btn--danger"
                    onClick={() => removeImage(index)}
                  >
                    Eliminar
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

<section id="product-price" className="product-form__section">
        <h2>Precio y promoción</h2>
        <div className="admin-form__row">
          <div className="admin-form__group">
            <label htmlFor="salePrice">Precio venta (COP) *</label>
            <input
              id="salePrice"
              type="number"
              min="0"
              value={form.salePrice}
              onChange={(e) => setField("salePrice", e.target.value)}
              required
            />
          </div>
          <div className="admin-form__group">
            <label htmlFor="internalCost">Costo interno (COP)</label>
            <input
              id="internalCost"
              type="number"
              min="0"
              value={form.internalCost}
              onChange={(e) => setField("internalCost", e.target.value)}
            />
          </div>
          <div className="admin-form__group">
            <label htmlFor="discountPercent">Descuento %</label>
            <input
              id="discountPercent"
              type="number"
              min="0"
              max="100"
              value={form.discountPercent}
              onChange={(e) => setField("discountPercent", e.target.value)}
            />
          </div>
        </div>
        <label className="admin-checkbox">
          <input
            type="checkbox"
            checked={form.onPromotion}
            onChange={(e) => setField("onPromotion", e.target.checked)}
          />
          En promoción
        </label>
      </section>

<section id="product-variants" className="product-form__section">
        <h2>Presentaciones y variantes</h2>
        <p className="product-form__hint product-form__hint--tight">
          El SKU identifica cada presentación. Talla y color son opcionales: no agregues opciones que el producto no necesita. El stock existente se modifica con ajustes relativos, no al guardar estos datos.
        </p>
        <div className="variant-table-wrap">
          <div className="variant-table">
            <div className="variant-table__head" aria-hidden="true">
              <span>Talla</span>
              <span>Color</span>
              <span>SKU</span>
              <span>Stock</span>
              <span>Precio</span>
              <span>Activa</span>
              <span />
            </div>
            {form.variants.map((variant, index) => {
              const skuKey = String(variant.sku || "").trim().toUpperCase();
              const comboKey =
                variant.isActive !== false
                  ? `${variant.size || ""}|${variant.color || ""}`
                  : "";
              const hasError =
                skuDupSet.has(skuKey) || comboDupSet.has(comboKey);
              return (
                <div
                  key={variant.clientKey || variant.id || `variant-${index}`}
                  className={`variant-row${hasError ? " variant-row--error" : ""}`}
                >
                  <label>Talla (opcional)<select
                    value={variant.size}
                    onChange={(e) => setVariant(index, "size", e.target.value)}
                    aria-label={`Talla variante ${index + 1}`}
                  >
                    <option value="">No aplica</option>
                    {sizes.map((s) => (
                      <option key={s._id} value={s._id}>
                        {s.name}
                      </option>
                    ))}
                  </select></label>
                  <label>Color (opcional)<select
                    value={variant.color}
                    onChange={(e) => setVariant(index, "color", e.target.value)}
                    aria-label={`Color variante ${index + 1}`}
                  >
                    <option value="">No aplica</option>
                    {colors.map((c) => (
                      <option key={c._id} value={c._id}>
                        {c.name}
                      </option>
                    ))}
                  </select></label>
                  <label>SKU<input
                    className="variant-row__sku"
                    onChange={(e) => setVariant(index, "sku", e.target.value.toUpperCase())}
                    value={variant.sku}
                    aria-label={`SKU variante ${index + 1}`}
                    title="SKU único de la presentación"
                    autoComplete="off"
                  /></label>
                  <label>Existencias<input
                    type="number"
                    min="0"
                    placeholder="0"
                    step="1"
                    readOnly={!!variant.id}
                    title={variant.id ? "El stock se cambia mediante un ajuste con motivo" : "Stock inicial"}
                    value={variant.stock}
                    onChange={(e) => setVariant(index, "stock", e.target.value)}
                    required={!variant.id}
                    aria-label={`Stock variante ${index + 1}`}
                  /></label>
                  <label>Precio propio (opcional)<input
                    type="number"
                    min="0"
                    placeholder="Opcional"
                    value={variant.price}
                    onChange={(e) => setVariant(index, "price", e.target.value)}
                    aria-label={`Precio variante ${index + 1}`}
                  /></label>
                  <label className="admin-checkbox admin-checkbox--inline">
                    <input
                      type="checkbox"
                      checked={variant.isActive}
                      onChange={(e) =>
                        setVariant(index, "isActive", e.target.checked)
                      }
                    />
                    <span className="variant-row__active-label">Activa</span>
                  </label>
                  {variant.id && <details className="variant-adjustment-legacy"><summary>Ajuste relativo en este formulario</summary><p>Al registrar confirmas el ajuste con motivo. Stock previsto: {variant.stock + (Number(variant.adjustmentDelta) || 0)}. El resultado se comprueba en el servidor.</p>
                    <input type="number" step="1" placeholder="Ajuste + / −" aria-label="Cantidad del ajuste"
                      disabled={adjustmentStates[variant.id]?.status === "processing" || adjustmentStates[variant.id]?.retryPending}
                      value={variant.adjustmentDelta || ""} onChange={(e) => setAdjustmentField(index, "adjustmentDelta", e.target.value)} />
                    <input placeholder="Motivo del ajuste" aria-label="Motivo del ajuste"
                      disabled={adjustmentStates[variant.id]?.status === "processing" || adjustmentStates[variant.id]?.retryPending}
                      value={variant.adjustmentReason || ""} onChange={(e) => setAdjustmentField(index, "adjustmentReason", e.target.value)} />
                    <button type="button" className="admin-btn" onClick={() => handleStockAdjustment(index)}
                      disabled={adjustmentStates[variant.id]?.status === "processing"}>
                      {adjustmentStates[variant.id]?.status === "processing" ? "Registrando…" : adjustmentStates[variant.id]?.retryPending ? "Reintentar ajuste" : "Registrar ajuste"}
                    </button>
                    {adjustmentStates[variant.id] && <p role={adjustmentStates[variant.id].status === "error" ? "alert" : "status"}>
                      {adjustmentStates[variant.id].message}
                    </p>}
                  </details>}
                  {form.variants.length > 1 ? (
                    <button
                      type="button"
                      className="variant-row__remove"
                      onClick={() => removeVariant(index)}
                      aria-label={`Quitar variante ${index + 1}`}
                    >
                      {variant.id ? "Desactivar variante" : "Quitar variante nueva"}
                    </button>
                  ) : (
                    <span className="variant-row__remove-placeholder" />
                  )}
                </div>
              );
            })}
          </div>
        </div>
        {(skuDupSet.size > 0 || comboDupSet.size > 0) && (
          <p className="admin-form-error variant-table__alert">
            {skuDupSet.size > 0
              ? "Hay SKUs duplicados. Quita la variante repetida o recarga para generar uno nuevo."
              : "Hay variantes con la misma talla y color."}
          </p>
        )}
        <button type="button" className="admin-btn admin-btn--sm" onClick={addVariant}>
          + Variante
        </button>
      </section>

<section id="product-publication" className="product-form__section">
        <h2>Publicación y posicionamiento</h2>
        <div className="admin-form__flags">
          <label className="admin-checkbox">
            <input
              type="checkbox"
              checked={form.isActive}
              onChange={(e) => setField("isActive", e.target.checked)}
            />
            Activo en tienda
          </label>
          <label className="admin-checkbox">
            <input
              type="checkbox"
              checked={form.isFeatured}
              onChange={(e) => setField("isFeatured", e.target.checked)}
            />
            Destacado
          </label>
          <label className="admin-checkbox">
            <input
              type="checkbox"
              checked={form.isNew}
              onChange={(e) => setField("isNew", e.target.checked)}
            />
            Nuevo
          </label>
          <label className="admin-checkbox">
            <input
              type="checkbox"
              checked={form.allowsCustomization}
              onChange={(e) =>
                setField("allowsCustomization", e.target.checked)
              }
            />
            Permite personalización
          </label>
        </div>
        <div className="admin-form__group">
          <label htmlFor="seoTitle">Título SEO</label>
          <input
            id="seoTitle"
            value={form.seoTitle}
            onChange={(e) => setField("seoTitle", e.target.value)}
          />
        </div>
        <div className="admin-form__group">
          <label htmlFor="seoDescription">Descripción SEO</label>
          <textarea
            id="seoDescription"
            rows={2}
            value={form.seoDescription}
            onChange={(e) => setField("seoDescription", e.target.value)}
          />
        </div>
      </section>

      <div className="admin-form__actions">
        <button
          type="submit"
          className="admin-btn admin-btn--primary"
          disabled={saving}
        >
          {saving ? "Guardando…" : isEdit ? "Guardar cambios" : "Crear producto"}
        </button>
        <Link href={returnTo} className="admin-btn">
          Cancelar
        </Link>
      </div>
    </form>
  );
}

